package com.example.events;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

import org.springframework.test.web.servlet.MockMvc;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** The OpenAPI document generated by the running context, and the committed clean baseline, for comparison. */
public final class GeneratedContract {

	private static final JsonMapper MAPPER = JsonMapper.builder().build();

	private GeneratedContract() {
	}

	public static JsonNode generated(MockMvc mockMvc) throws Exception {
		return MAPPER.readTree(mockMvc.perform(get("/v3/api-docs").with(request -> {
					request.setServerPort(8082);
					return request;
				}))
				.andReturn().getResponse().getContentAsString(StandardCharsets.UTF_8));
	}

	public static JsonNode baseline() throws Exception {
		return MAPPER.readTree(Files.readString(OpenApiBaselineExport.BASELINE));
	}

}
